#!/usr/bin/env bash
# Usage: tests/run_pins.sh tests/c2/pins_basic     (needs <name>.asm; expected pins generated by tests/c2/pin_gen.py)
set -euo pipefail
name=$1; b=build/pins/$(basename "$name"); mkdir -p "$b" logs
python3 tests/asm.py "$name.asm" "$b"
python3 tests/c2/pin_gen.py "$name.asm" > "$b/exp.pins"
defs=(); for n in 0 1 2 3 4 5 6 7; do defs+=("-DROM$n=\"$b/rom$n.hex\""); done
iverilog -g2012 "${defs[@]}" -o "$b/sim.vvp" tb/tb_pins.sv $(find rtl -name '*.v')
vvp -n "$b/sim.vvp" +EXP="$b/exp.pins" 2>&1 | tee "logs/pins_$(basename "$name").log"
grep -q '^PASS' "logs/pins_$(basename "$name").log"
